// Puzzle generation and validation for ORDERLE and FERMI
// Generates a full year of puzzles following the weekly rotation schedule

export interface OrderlePuzzle {
  category: string;
  rule: string;
  items: string[];
  reveal: string;
  citation: string;
  difficulty: string;
  reverse?: boolean;
}

export interface FermiPuzzle {
  category: string;
  units: string;
  prompt: string;
  answer: number;
  reveal: string;
  citation: string;
  difficulty: string;
}

