// ─── Weekly scheduler ─────────────────────────────────────────────────────

function getDayOfWeek(date: Date): number {
  // 0 = Sunday, 1 = Monday, ..., 6 = Saturday
  return date.getDay();
}

export function generateOrderleForDate(date: Date): OrderlePuzzle {
  const dow = getDayOfWeek(date);
  let category: string;

  if (dow === 1) { category = "cooking"; }
  else if (dow === 2) { category = "science"; }
  else if (dow === 3) { category = "history"; }
  else if (dow === 4) { category = "grammar"; }
  else if (dow === 5) { category = "everyday"; }
  else if (dow === 6) { category = "mixed"; }
  else { category = "biology"; } // Sunday

  const pool = ORDERLE_BANK.filter(p => p.category === category);
  // Deterministic pick based on date
  const weekNum = Math.floor((date.getTime() - new Date('2026-01-05').getTime()) / (7 * 86400000));
  return pool[Math.abs(weekNum) % pool.length];
}

export function generateFermiForDate(date: Date): FermiPuzzle {
  const weekNum = Math.floor((date.getTime() - new Date('2026-01-05').getTime()) / (7 * 86400000));
  // Simple rotation through the bank
  return FERMI_BANK[Math.abs(weekNum) % FERMI_BANK.length];
}

// ─── Validation ───────────────────────────────────────────────────────────

export function validateOrderlePuzzle(p: OrderlePuzzle): string[] {
  const errors: string[] = [];
  if (!p.items || p.items.length < 3) errors.push("Needs at least 3 items");
  if (!p.rule) errors.push("Missing rule");
  if (!p.reveal || p.reveal.length < 20) errors.push("Reveal too short (min 20 chars)");
  if (!p.citation) errors.push("Missing citation");
  if (new Set(p.items).size !== p.items.length) errors.push("Duplicate items");
  return errors;
}

export function validateFermiPuzzle(p: FermiPuzzle): string[] {
  const errors: string[] = [];
  if (!p.prompt) errors.push("Missing prompt");
  if (!isFinite(p.answer) || p.answer <= 0) errors.push("Answer must be positive number");
  if (!p.reveal || p.reveal.length < 20) errors.push("Reveal too short");
  if (!p.citation) errors.push("Missing citation");
  if (!p.units) errors.push("Missing units");
  return errors;
}

export function validateAll(): { orderle: number; fermi: number; olErrors: number; fmErrors: number } {
  let olErrors = 0, fmErrors = 0;
  for (const p of ORDERLE_BANK) olErrors += validateOrderlePuzzle(p).length;
  for (const p of FERMI_BANK) fmErrors += validateFermiPuzzle(p).length;
  return { orderle: ORDERLE_BANK.length, fermi: FERMI_BANK.length, olErrors, fmErrors };
}

// Export the full banks for static export
export { ORDERLE_BANK, FERMI_BANK };
